public static int What(int k, int[] A, int s, int e)
{
    if (s == e)
        if (A[s] > k)
            return A[s];
        else
            return 0;
    else
    {
        int p1 = What(k, A, s, (s + e) / 2);
        int p2 = What(k, A, ((s + e) / 2)+1, e);
        return p1 + p2;
    }
}

